contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, uint amount) public payable {
        require(target == address(this));
        uint n0 = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint b0 = address(c).balance;
        require(amount <= b0);
        c.sendMoney(target, amount); if (__ESBMC_reverted()) return;
        assert(c.depositsCount() == n0 && address(c).balance + amount == b0);
    }
    receive() external payable {}
}

