        c = new SimpleWallet();
    }

    function _run(address target, uint256 amount) internal {
        target = address(this);
        uint256 n0;
        try c.depositsCount() returns (uint256 __r) { n0 = __r; } catch { return; }
        uint b0 = address(c).balance;
        vm.assume(amount <= b0);
        try c.sendMoney(target, amount) {} catch { return; }
        assertTrue(c.depositsCount() == n0 && address(c).balance + amount == b0);
    }

    function testFuzz_run(address target, uint256 amount) public {
        _run(target, amount);
    }

